import pandas as pd, json
from datetime import datetime, timedelta

p = pd.read_csv('data/payments.csv')
b = p[p['merchant']=='Belles_cookbook_store'].copy()
b['date'] = b.apply(lambda r: datetime(int(r['year']),1,1) + timedelta(days=int(r['day_of_year'])-1), axis=1)
mar = b[(b['date'].dt.year==2023) & (b['date'].dt.month==3)]
monthly_volume = mar['eur_amount'].sum()
fraud_rate = mar[mar['has_fraudulent_dispute']==True]['eur_amount'].sum() / mar['eur_amount'].sum() * 100

account_type = 'R'
mcc = 5942

fees = json.load(open('data/fees.json'))

def parse_num(x):
    x=x.strip().replace('%','')
    if x.endswith('k'): return float(x[:-1])*1000
    if x.endswith('m'): return float(x[:-1])*1000000
    return float(x)

def in_range(rule_val, actual):
    if rule_val is None: return True
    s = rule_val.strip()
    if s.startswith('>'):
        return actual > parse_num(s[1:])
    if s.startswith('<'):
        return actual < parse_num(s[1:])
    if '-' in s:
        parts = s.split('-')
        lo, hi = parse_num(parts[0]), parse_num(parts[1])
        return lo <= actual <= hi
    return False

def cap_delay_match(rule, actual_days):
    if rule is None: return True
    if rule == 'immediate': return actual_days == 0
    if rule == 'manual': return False
    if rule == '>5': return actual_days > 5
    if rule == '<3': return actual_days < 3
    if rule == '3-5': return 3 <= actual_days <= 5
    return False

applicable = []
for f in fees:
    if f['account_type'] and account_type not in f['account_type']:
        continue
    if f['merchant_category_code'] and mcc not in f['merchant_category_code']:
        continue
    if not cap_delay_match(f['capture_delay'], 1):
        continue
    if f['monthly_fraud_level'] is not None and not in_range(f['monthly_fraud_level'], fraud_rate):
        continue
    if f['monthly_volume'] is not None and not in_range(f['monthly_volume'], monthly_volume):
        continue
    applicable.append(f['ID'])

print("Applicable fees count:", len(applicable))
print(",".join(str(x) for x in sorted(applicable)))
