import json

with open('data/fees.json') as f:
    fees = json.load(f)

merchant = {'capture_delay': '1', 'merchant_category_code': 5942, 'account_type': 'R'}
# capture_delay '1' means 1 day => matches '<3' and 'immediate'? '1' < 3 so '<3'
# monthly volume March: 116436 => 100k-1m
# fraud ratio ~10.2% => need to check ranges
# We'll match rules where each specified field either is null/empty OR contains our merchant's value.

def matches(fee):
    # account_type
    at = fee.get('account_type')
    if at and len(at)>0 and 'R' not in at:
        return False
    # capture_delay: merchant capture_delay is '1' meaning 1 day, which fits '<3' and 'immediate' would be 0? '1' -> '<3'
    cd = fee.get('capture_delay')
    if cd is not None:
        if cd == '<3':
            pass  # 1 < 3, ok
        elif cd == 'immediate':
            return False  # 1 day is not immediate
        elif cd == 'manual':
            return False
        elif cd == '3-5':
            return False
        elif cd == '>5':
            return False
    # monthly_fraud_level - ratio 10.2%
    mfl = fee.get('monthly_fraud_level')
    if mfl is not None:
        # ranges like '7.7%-8.3%' or '>8.3%' or '<7.7%'
        s = mfl.replace('%','')
        if '-' in s:
            lo,hi = s.split('-')
            if not (float(lo) <= 10.2 <= float(hi)):
                return False
        elif s.startswith('>'):
            if not (10.2 > float(s[1:])):
                return False
        elif s.startswith('<'):
            if not (10.2 < float(s[1:])):
                return False
    # monthly_volume - 116436
    mv = fee.get('monthly_volume')
    if mv is not None:
        # like '100k-1m'
        def parse(x):
            x=x.strip()
            if x.endswith('k'): return float(x[:-1])*1000
            if x.endswith('m'): return float(x[:-1])*1_000_000
            return float(x)
        if '-' in mv:
            lo,hi = mv.split('-')
            if not (parse(lo) <= 116436 <= parse(hi)):
                return False
        elif mv.startswith('>'):
            if not (116436 > parse(mv[1:])):
                return False
        elif mv.startswith('<'):
            if not (116436 < parse(mv[1:])):
                return False
    # mcc
    mcc = fee.get('merchant_category_code')
    if mcc and len(mcc)>0 and 5942 not in mcc:
        return False
    return True

matched = [f['ID'] for f in fees if matches(f)]
print(len(matched))
print(matched)
