import json
fees = json.load(open('data/fees.json'))
print("Total fees:", len(fees))

merchant = {
    'account_type': 'R',
    'mcc': 5942,
    'capture_delay': '<3',  # capture_delay = 1 day
    'monthly_volume_bucket': '100k-1m',
    'monthly_fraud_level': '>8.3%',
}

def match(fee):
    # account_type
    if fee['account_type'] and merchant['account_type'] not in fee['account_type']:
        return False
    # mcc
    if fee['merchant_category_code'] and merchant['mcc'] not in fee['merchant_category_code']:
        return False
    # capture_delay
    cd = fee['capture_delay']
    if cd is not None:
        # merchant capture_delay is 1 day -> "<3"
        if cd == '<3':
            ok = True
        elif cd == 'immediate':
            ok = False
        elif cd == '3-5':
            ok = False
        elif cd == '>5':
            ok = False
        elif cd == 'manual':
            ok = False
        else:
            ok = False
        if not ok:
            return False
    # monthly_volume
    mv = fee['monthly_volume']
    if mv is not None:
        if mv != '100k-1m':
            return False
    # monthly_fraud_level
    mfl = fee['monthly_fraud_level']
    if mfl is not None:
        if mfl != '>8.3%':
            return False
    return True

matching = [f['ID'] for f in fees if match(f)]
print("Matching IDs:", matching)
print("count:", len(matching))
EOF"}

