total_vol = b['eur_amount'].sum()
fraud_vol = b[b['has_fraudulent_dispute']==True]['eur_amount'].sum()
fraud_rate = fraud_vol/total_vol*100
print(f"Total: {total_vol:.2f}, fraud: {fraud_vol:.2f}, rate: {fraud_rate:.2f}%")

# Fraud transactions
fraud = b[b['has_fraudulent_dispute']==True].copy()
print("Fraud count:", len(fraud))

# For each candidate ACI (A,B,C,D,E,F) - skip G, we compute total fee
def match_rule(rule, tx, aci):
    if rule.get('account_type') and 'R' not in rule['account_type'] and rule['account_type']!=[]:
        return False
    if rule.get('merchant_category_code') and 5942 not in rule['merchant_category_code']:
        return False
    if rule.get('is_credit') is not None and rule['is_credit'] != bool(tx['is_credit']):
        return False
    if rule.get('aci') and aci not in rule['aci']:
        return False
    if rule.get('card_scheme') and rule['card_scheme'] != tx['card_scheme']:
        return False
    if rule.get('capture_delay') is not None:
        cd = rule['capture_delay']
        # merchant capture_delay = '1' => less than 3
        if cd == '<3':
            pass
        elif cd == 'immediate':
            return False
        elif cd == 'manual':
            return False
        elif cd == '3-5':
            return False
        elif cd == '>5':
            return False
    if rule.get('monthly_fraud_level') is not None:
        # parse ranges like '7.7%-8.3%'
        lvl = rule['monthly_fraud_level']
        # extract
        import re
        m = re.match(r'([\d.]+)%-([\d.]+)%', lvl)
        if m:
            lo,hi = float(m.group(1)), float(m.group(2))
            if not (lo <= fraud_rate <= hi): return False
        elif lvl.startswith('>'):
            v = float(lvl.replace('>','').replace('%',''))
            if not (fraud_rate > v): return False
        elif lvl.startswith('<'):
            v = float(lvl.replace('<','').replace('%',''))
            if not (fraud_rate < v): return False
    if rule.get('monthly_volume') is not None:
        mv = rule['monthly_volume']
        import re
        def parse(x):
            x=x.replace('k','000').replace('m','000000')
            return float(x)
        if '-' in mv:
            lo,hi = mv.split('-')
            lo,hi = parse(lo), parse(hi)
            if not (lo <= total_vol <= hi): return False
        elif mv.startswith('>'):
            v = parse(mv[1:])
            if not (total_vol>v): return False
        elif mv.startswith('<'):
            v = parse(mv[1:])
            if not (total_vol<v): return False
    if rule.get('intracountry') is not None:
        intra = (tx['issuing_country']==tx['acquirer_country'])
        if rule['intracountry'] != intra: return False
    return True

def find_fee(tx, aci):
    best = None
    for r in fees:
        if match_rule(r, tx, aci):
            fee = r['fixed_amount'] + r['rate']*tx['eur_amount']/10000
            if best is None or fee<best:
                best=fee
    return best

results = {}
for aci in ['A','B','C','D','E','F']:
    tot=0
    ok=True
    for _,tx in fraud.iterrows():
        f = find_fee(tx, aci)
        if f is None:
            ok=False; break
        tot+=f
    results[aci] = tot if ok else None
print(results)
