import pandas as pd, json
df = pd.read_csv('data/payments.csv')
fees = json.load(open('data/fees.json'))
b = df[(df.merchant=='Belles_cookbook_store') & (df.day_of_year<=31)]
fraud = b[b.has_fraudulent_dispute==True].copy()

# Merchant properties
mcc = 5942
account_type = 'R'
capture_delay = '1'  # from merchant data - matches '<3'

# Compute monthly volume & fraud rate for Jan for Belles
total_vol = b.eur_amount.sum()
fraud_vol = fraud.eur_amount.sum()
fraud_rate = fraud_vol/total_vol*100
print(f"Jan total vol: {total_vol:.2f}, fraud vol: {fraud_vol:.2f}, fraud rate: {fraud_rate:.2f}%")

def match_rule(rule, tx, target_aci):
    if rule.get('account_type') and account_type not in rule['account_type'] and rule['account_type']!=[]:
        return False
    if rule.get('merchant_category_code') and mcc not in rule['merchant_category_code']:
        return False
    if rule.get('card_scheme') and rule['card_scheme'] != tx['card_scheme']:
        return False
    if rule.get('is_credit') is not None and rule['is_credit'] != tx['is_credit']:
        return False
    if rule.get('aci') and target_aci not in rule['aci']:
        return False
    if rule.get('intracountry') is not None:
        intra = (tx['issuing_country']==tx['acquirer_country'])
        if rule['intracountry'] != intra:
            return False
    if rule.get('capture_delay'):
        cd = rule['capture_delay']
        # capture_delay for merchant='1' means 1 day = '<3'
        if cd=='<3':
            if capture_delay not in ['1','2','manual','immediate']: pass
            # merchant delay=1 → <3 matches
            ok = True
        elif cd=='immediate':
            ok = capture_delay=='immediate'
        elif cd=='manual':
            ok = capture_delay=='manual'
        elif cd=='3-5':
            ok = capture_delay in ['3','4','5']
        elif cd=='>5':
            ok = capture_delay.isdigit() and int(capture_delay)>5
        else:
            ok = True
        if not ok: return False
    if rule.get('monthly_fraud_level'):
        mfl = rule['monthly_fraud_level']
        # parse
        lo,hi = None,None
        if '%-' in mfl:
            a,b_ = mfl.split('%-')
            lo=float(a); hi=float(b_.replace('%',''))
        elif mfl.startswith('<'):
            hi=float(mfl.replace('<','').replace('%',''))
            lo=0
        elif mfl.startswith('>'):
            lo=float(mfl.replace('>','').replace('%',''))
            hi=1e9
        if not (lo<=fraud_rate<=hi): return False
    if rule.get('monthly_volume'):
        mv = rule['monthly_volume']
        lo,hi=0,1e18
        if mv=='100k-1m': lo,hi=100000,1000000
        elif mv=='1m-5m': lo,hi=1000000,5000000
        elif mv=='5m-10m': lo,hi=5000000,10000000
        elif mv.startswith('<'):
            hi=float(mv[1:].replace('k','000').replace('m','000000'))
        elif mv.startswith('>'):
            lo=float(mv[1:].replace('k','000').replace('m','000000'))
        if not (lo<=total_vol<=hi): return False
    return True

def compute_fee(tx, target_aci):
    best = None
    for rule in fees:
        if match_rule(rule, tx, target_aci):
            fee = rule['fixed_amount'] + rule['rate']*tx['eur_amount']/10000
            if best is None or fee<best:
                best = fee
    return best

acis = ['A','B','C','D','E','F','G']
results = {}
for aci in acis:
    total = 0
    ok=True
    for _,tx in fraud.iterrows():
        f = compute_fee(tx, aci)
        if f is None:
            ok=False; break
        total += f
    results[aci] = total if ok else None
print(results)
