import json, pandas as pd
from datetime import datetime, timedelta

df = pd.read_csv('data/payments.csv')
belles = df[df['merchant']=='Belles_cookbook_store'].copy()
belles['date'] = belles.apply(lambda r: datetime(int(r['year']),1,1)+timedelta(days=int(r['day_of_year'])-1), axis=1)

# The manual: monthly_volume/fraud rate applies to the merchant's monthly aggregates.
# For March 2023, we need PRIOR month's data? Or same month?
# Fees applicable to March 2023 - the rules apply based on that month's volume/fraud.
# Let's compute for March 2023
mar = belles[(belles['date'].dt.year==2023)&(belles['date'].dt.month==3)]
vol = mar['eur_amount'].sum()
fraud_rate = mar[mar['has_fraudulent_dispute']==True]['eur_amount'].sum()/vol*100
print(f'Volume: {vol}, Fraud rate: {fraud_rate}%')

# Merchant characteristics
mcc = 5942
acct = 'R'
# capture_delay is '1' from merchant data, which means 1 day -> '<3'

with open('data/fees.json') as f:
    fees = json.load(f)

def volume_match(rule_vol, v):
    if rule_vol is None: return True
    # formats: '100k-1m', '>5m', '<100k' etc.
    s = rule_vol
    def parse(x):
        x=x.strip()
        if x.endswith('k'): return float(x[:-1])*1000
        if x.endswith('m'): return float(x[:-1])*1_000_000
        return float(x)
    if '-' in s:
        a,b = s.split('-')
        return parse(a) <= v <= parse(b)
    if s.startswith('>'): return v > parse(s[1:])
    if s.startswith('<'): return v < parse(s[1:])
    return False

def fraud_match(rule_fraud, f):
    if rule_fraud is None: return True
    s = rule_fraud
    def parse(x):
        return float(x.strip().rstrip('%'))
    if '-' in s:
        a,b = s.split('-')
        return parse(a) <= f <= parse(b)
    if s.startswith('>'): return f > parse(s[1:])
    if s.startswith('<'): return f < parse(s[1:])
    return False

def capture_match(rule_cd, cd):
    if rule_cd is None: return True
    cd_int = int(cd)
    s = rule_cd
    if s == 'immediate': return cd_int == 0
    if s == 'manual': return False
    if '-' in s:
        a,b = s.split('-')
        return int(a) <= cd_int <= int(b)
    if s.startswith('>'): return cd_int > int(s[1:])
    if s.startswith('<'): return cd_int < int(s[1:])
    return False

applicable = []
for fee in fees:
    # account_type
    if fee['account_type'] and acct not in fee['account_type']:
        continue
    if fee['merchant_category_code'] and mcc not in fee['merchant_category_code']:
        continue
    if not capture_match(fee['capture_delay'], '1'):
        continue
    if not volume_match(fee['monthly_volume'], vol):
        continue
    if not fraud_match(fee['monthly_fraud_level'], fraud_rate):
        continue
    applicable.append(fee['ID'])

print('Count:', len(applicable))
print(applicable)
