mdict = {m['merchant']:m for m in merchants}
acq = pd.read_csv('acquirer_countries.csv')
acq_country = dict(zip(acq['acquirer'], acq['country_code']))

MERCH='Golfclub_Baron_Friso'
minfo = mdict[MERCH]
acquirer_country = acq_country[minfo['acquirer'][0]]  # medici -> IT

start = datetime.date(2023,6,1).timetuple().tm_yday
end = datetime.date(2023,6,30).timetuple().tm_yday

m = df[df['merchant']==MERCH].copy()
june = m[(m['day_of_year']>=start)&(m['day_of_year']<=end)]

monthly_volume = june['eur_amount'].sum()
fraud_volume = june[june['has_fraudulent_dispute']==True]['eur_amount'].sum()
fraud_level = fraud_volume/monthly_volume*100

def in_range(val, spec):
    # spec like '100k-1m', '7.7%-8.3%', '>5', '<3'
    def parse(s):
        s=s.replace('%','')
        s=s.replace('k','e3').replace('m','e6')
        return float(s)
    spec=spec.strip()
    if spec.startswith('>'):
        return val > parse(spec[1:])
    if spec.startswith('<'):
        return val < parse(spec[1:])
    if '-' in spec:
        a,b=spec.split('-')
        return parse(a) <= val <= parse(b)
    return False

def match(fee, tx):
    if fee['card_scheme'] != tx['card_scheme']: return False
    if fee['account_type'] and minfo['account_type'] not in fee['account_type']: return False
    if fee['capture_delay'] is not None:
        if not (fee['capture_delay']==minfo['capture_delay']): 
            # capture_delay could be range too
            cd=minfo['capture_delay']
            spec=fee['capture_delay']
            try: cdv=float(cd)
            except: cdv=None
            if cdv is not None and spec in ('>5','<3','3-5'):
                if not in_range(cdv,spec): return False
            elif spec=='immediate' or spec=='manual':
                return False
            elif cdv is None:
                return False
    if fee['monthly_fraud_level'] is not None:
        if not in_range(fraud_level, fee['monthly_fraud_level']): return False
    if fee['monthly_volume'] is not None:
        if not in_range(monthly_volume, fee['monthly_volume']): return False
    if fee['merchant_category_code'] and minfo['merchant_category_code'] not in fee['merchant_category_code']: return False
    if fee['is_credit'] is not None and fee['is_credit'] != tx['is_credit']: return False
    if fee['aci'] and tx['aci'] not in fee['aci']: return False
    if fee['intracountry'] is not None:
        intra = (tx['issuing_country']==acquirer_country)
        if fee['intracountry'] != intra: return False
    return True

total=0.0
unmatched=0
for _,tx in june.iterrows():
    matched=None
    for fee in fees:
        if match(fee, tx):
            matched=fee
            break
    if matched is None:
        unmatched+=1
        continue
    total += matched['fixed_amount'] + matched['rate']*tx['eur_amount']/10000

print('unmatched', unmatched)
print('total fees', round(total,2))
