def month_of(doy, year=2023):
    return (datetime.date(year,1,1) + datetime.timedelta(days=int(doy)-1)).month
rafa['month'] = rafa['day_of_year'].apply(month_of)
monthly_vol = rafa.groupby('month')['eur_amount'].sum().to_dict()
fraud_vol = rafa[rafa['has_fraudulent_dispute']==True].groupby('month')['eur_amount'].sum().to_dict()

def vol_bucket(v):
    # buckets we see in fees: '100k-1m', '1m-5m', '5m-10m', etc, and '<100k'
    return v

def vol_match(rule_str, v):
    if rule_str is None: return True
    if rule_str.startswith('<'):
        return v < parse(rule_str[1:])
    if rule_str.startswith('>'):
        return v > parse(rule_str[1:])
    a,b = rule_str.split('-')
    return parse(a) <= v < parse(b)

def parse(s):
    s=s.strip()
    if s.endswith('k'): return float(s[:-1])*1000
    if s.endswith('m'): return float(s[:-1])*1_000_000
    if s.endswith('%'): return float(s[:-1])/100
    return float(s)

def fraud_match(rule_str, r):
    if rule_str is None: return True
    if rule_str.startswith('<'):
        return r < parse(rule_str[1:])
    if rule_str.startswith('>'):
        return r > parse(rule_str[1:])
    a,b = rule_str.split('-')
    return parse(a) <= r < parse(b)

def find_fee(tx, mcc, monthly_v, fraud_r):
    matches = []
    for rule in fees:
        if rule['card_scheme'] != tx['card_scheme']: continue
        if rule['account_type'] and 'D' not in rule['account_type']: continue
        if rule['capture_delay'] is not None and rule['capture_delay'] != '>5': continue
        if not vol_match(rule['monthly_volume'], monthly_v): continue
        if not fraud_match(rule['monthly_fraud_level'], fraud_r): continue
        if rule['merchant_category_code'] and mcc not in rule['merchant_category_code']: continue
        if rule['is_credit'] is not None and rule['is_credit'] != tx['is_credit']: continue
        if rule['aci'] and tx['aci'] not in rule['aci']: continue
        if rule['intracountry'] is not None:
            intra = tx['issuing_country'] == tx['acquirer_country']
            if rule['intracountry'] != bool(intra): continue
        matches.append(rule)
    return matches

def compute_fees(mcc):
    total = 0.0
    unmatched = 0
    for idx, tx in rafa.iterrows():
        m = tx['month']
        mv = monthly_vol[m]
        fr = fraud_vol.get(m,0)/mv
        rules = find_fee(tx, mcc, mv, fr)
        if not rules:
            unmatched += 1
            continue
        # pick first? or take the most specific? Let's just pick first match
        rule = rules[0]
        total += rule['fixed_amount'] + rule['rate']*tx['eur_amount']/10000
    return total, unmatched

