import pandas as pd, json
from datetime import datetime, timedelta

df = pd.read_csv('data/payments.csv')
def doy_to_month(doy, year=2023):
    return (datetime(year,1,1)+timedelta(days=int(doy)-1)).month
df['month'] = df['day_of_year'].apply(doy_to_month)

bcs = df[(df.merchant=='Belles_cookbook_store') & (df.year==2023) & (df.day_of_year==100)].copy()

with open('data/fees.json') as f:
    fees = json.load(f)
with open('data/merchant_data.json') as f:
    md = json.load(f)
m = [x for x in md if x['merchant']=='Belles_cookbook_store'][0]
print(m)

# monthly volume as of April: 107343.79 -> which bucket? 
# Common buckets: '100k-1m'
vol = 107343.79
fraud_pct = 9.1458

def match(fee, txn, merchant, vol, fraud_pct):
    if fee['card_scheme'] != txn['card_scheme']: return False
    if fee['account_type'] and merchant['account_type'] not in fee['account_type']: return False
    if fee['capture_delay'] is not None:
        cd = merchant['capture_delay']
        rule = fee['capture_delay']
        # cd is '1' - a number
        try: cdn = int(cd)
        except: cdn = None
        if rule=='manual':
            if cd != 'manual': return False
        elif rule=='immediate':
            if cd != 'immediate': return False
        elif rule=='<3':
            if cdn is None or cdn >= 3: return False
        elif rule=='3-5':
            if cdn is None or not (3<=cdn<=5): return False
        elif rule=='>5':
            if cdn is None or cdn <= 5: return False
    if fee['monthly_fraud_level'] is not None:
        rule = fee['monthly_fraud_level']
        # like '7.7%-8.3%' or '<7.7%' etc
        r = rule.replace('%','')
        if '-' in r:
            lo,hi = r.split('-')
            if not (float(lo) <= fraud_pct <= float(hi)): return False
        elif r.startswith('<'):
            if not (fraud_pct < float(r[1:])): return False
        elif r.startswith('>'):
            if not (fraud_pct > float(r[1:])): return False
    if fee['monthly_volume'] is not None:
        rule = fee['monthly_volume']
        def parse(v):
            v=v.replace('k','000').replace('m','000000')
            return float(v)
        if '-' in rule:
            lo,hi = rule.split('-')
            if not (parse(lo) <= vol <= parse(hi)): return False
        elif rule.startswith('<'):
            if not (vol < parse(rule[1:])): return False
        elif rule.startswith('>'):
            if not (vol > parse(rule[1:])): return False
    if fee['merchant_category_code'] and merchant['merchant_category_code'] not in fee['merchant_category_code']: return False
    if fee['is_credit'] is not None:
        if bool(fee['is_credit']) != bool(txn['is_credit']): return False
    if fee['aci'] and txn['aci'] not in fee['aci']: return False
    if fee['intracountry'] is not None:
        intra = (txn['issuing_country'] == txn['acquirer_country'])
        if bool(fee['intracountry']) != intra: return False
    return True

total = 0
for _,txn in bcs.iterrows():
    matches = [f for f in fees if match(f, txn, m, vol, fraud_pct)]
    if len(matches)==0:
        print('NO MATCH', txn.psp_reference, txn.card_scheme, txn.aci, txn.is_credit)
        continue
    # If multiple, prefer most specific (fewest nulls). Actually spec says rules; likely one match.
    if len(matches)>1:
        # choose most specific: most non-null constraint fields
        def spec(f):
            keys=['account_type','capture_delay','monthly_fraud_level','monthly_volume','merchant_category_code','is_credit','aci','intracountry']
            s=0
            for k in keys:
                v=f[k]
                if v is not None and v!=[]: s+=1
            return s
        matches.sort(key=spec, reverse=True)
    f = matches[0]
    fee = f['fixed_amount'] + f['rate']*txn['eur_amount']/10000
    total += fee

print('Total fees:', round(total,2))
