def match_range(rule_str, value):
    if rule_str is None: return True
    s = rule_str
    def parse(v):
        v = v.strip().replace('%','')
        if v.endswith('k'): return float(v[:-1])*1000
        if v.endswith('m'): return float(v[:-1])*1000000
        return float(v)
    if s.startswith('<'): return value < parse(s[1:])
    if s.startswith('>'): return value > parse(s[1:])
    if '-' in s:
        a,b = s.split('-')
        return parse(a) <= value <= parse(b)
    return False
