import pandas as pd, json
import numpy as np

df = pd.read_csv('data/payments.csv')
with open('data/fees.json') as f:
    fees = json.load(f)
with open('data/merchant_data.json') as f:
    merchants = json.load(f)

merchant_info = next(m for m in merchants if m['merchant']=='Martinis_Fine_Steakhouse')

mfs = df[(df.merchant=='Martinis_Fine_Steakhouse') & (df.year==2023)].copy()
mfs['date'] = pd.to_datetime(mfs['year'].astype(str)+'-01-01') + pd.to_timedelta(mfs['day_of_year']-1, unit='D')
mfs['month'] = mfs['date'].dt.month
mfs['intracountry'] = mfs['issuing_country']==mfs['acquirer_country']

# monthly volumes and fraud rate for the merchant
monthly_stats = mfs.groupby('month').apply(lambda g: pd.Series({
    'vol': g['eur_amount'].sum(),
    'fraud_vol': g.loc[g['has_fraudulent_dispute']==True,'eur_amount'].sum()
}))
monthly_stats['fraud_rate'] = monthly_stats['fraud_vol']/monthly_stats['vol']*100

def vol_bucket_match(rule_val, vol):
    if rule_val is None: return True
    # possible: '100k-1m', '<100k', '>5m', etc.
    r = rule_val
    def parse(s):
        s = s.replace('k','e3').replace('m','e6')
        return float(s)
    if r.startswith('<'):
        return vol < parse(r[1:])
    if r.startswith('>'):
        return vol > parse(r[1:])
    a,b = r.split('-')
    return parse(a) <= vol < parse(b)

def fraud_bucket_match(rule_val, fr):
    if rule_val is None: return True
    r = rule_val.replace('%','')
    if r.startswith('<'):
        return fr < float(r[1:])
    if r.startswith('>'):
        return fr > float(r[1:])
    a,b = r.split('-')
    return float(a) <= fr < float(b)

def find_fee(tx, mcc, account_type, capture_delay, monthly_vol, monthly_fraud):
    matches = []
    for rule in fees:
        if rule['card_scheme'] != tx['card_scheme']: continue
        if rule['account_type'] and account_type not in rule['account_type']: continue
        if rule['capture_delay'] is not None and rule['capture_delay'] != capture_delay:
            # capture_delay comparisons - merchant's is 'immediate'
            # Actually rule capture_delay can be '3-5','>5','<3','immediate','manual'
            # Need to match merchant's capture_delay literally
            continue
        if rule['merchant_category_code'] and mcc not in rule['merchant_category_code']: continue
        if rule['is_credit'] is not None and rule['is_credit'] != tx['is_credit']: continue
        if rule['aci'] and tx['aci'] not in rule['aci']: continue
        if rule['intracountry'] is not None:
            if bool(rule['intracountry']) != bool(tx['intracountry']): continue
        if not vol_bucket_match(rule['monthly_volume'], monthly_vol): continue
        if not fraud_bucket_match(rule['monthly_fraud_level'], monthly_fraud): continue
        matches.append(rule)
    if len(matches) != 1:
        return matches
    r = matches[0]
    return r['fixed_amount'] + r['rate']*tx['eur_amount']/10000

# Test on one row
sample = mfs.iloc[0]
month = sample['month']
mv = monthly_stats.loc[month,'vol']
mf = monthly_stats.loc[month,'fraud_rate']
res = find_fee(sample, 5812, 'H', 'immediate', mv, mf)
print("sample result:", res if not isinstance(res,list) else f"{len(res)} matches")
if isinstance(res,list):
    for r in res[:5]: print(r)
