import json, pandas as pd
fees = json.load(open('data/fees.json'))
df = pd.read_csv('data/payments.csv')
r = df[(df['merchant']=='Rafa_AI') & (df['year']==2023)].copy()

merchant = {'account_type':'D','merchant_category_code':7372}
r['intracountry'] = (r['issuing_country'] == r['acquirer_country'])
r['date'] = pd.to_datetime(r['year'].astype(str)+'-01-01') + pd.to_timedelta(r['day_of_year']-1, unit='D')
r['month'] = r['date'].dt.month

monthly = r.groupby('month').agg(vol=('eur_amount','sum'), fraud_vol=('eur_amount', lambda x: x[r.loc[x.index,'has_fraudulent_dispute']].sum()))
monthly['fraud_rate'] = monthly['fraud_vol']/monthly['vol']
month_vol = monthly['vol'].to_dict()
month_fraud = (monthly['fraud_rate']*100).to_dict()

def vol_match(rule, vol):
    if rule is None: return True
    # formats: '100k-1m', '<100k', '>5m' etc
    def parse(s):
        s=s.replace('k','e3').replace('m','e6')
        return float(s)
    if '-' in rule:
        a,b = rule.split('-'); return parse(a) <= vol <= parse(b)
    if rule.startswith('<'): return vol < parse(rule[1:])
    if rule.startswith('>'): return vol > parse(rule[1:])
    return True

def fraud_match(rule, fr):
    if rule is None: return True
    def parse(s): return float(s.replace('%',''))
    if '-' in rule:
        a,b = rule.split('-'); return parse(a) <= fr <= parse(b)
    if rule.startswith('<'): return fr < parse(rule[1:])
    if rule.startswith('>'): return fr > parse(rule[1:])
    return True

def find_fee(scheme, tx):
    mv = month_vol[tx['month']]
    mfr = month_fraud[tx['month']]
    candidates = []
    for f in fees:
        if f['card_scheme'] != scheme: continue
        if f['account_type'] and 'D' not in f['account_type']: continue
        if f['capture_delay'] is not None and f['capture_delay'] != '>5': continue
        if f['merchant_category_code'] and 7372 not in f['merchant_category_code']: continue
        if f['is_credit'] is not None and f['is_credit'] != tx['is_credit']: continue
        if f['aci'] and tx['aci'] not in f['aci']: continue
        if f['intracountry'] is not None and bool(f['intracountry']) != bool(tx['intracountry']): continue
        if not vol_match(f['monthly_volume'], mv): continue
        if not fraud_match(f['monthly_fraud_level'], mfr): continue
        candidates.append(f)
    return candidates

schemes = ['GlobalCard','NexPay','TransactPlus','SwiftCharge']
totals = {}
for s in schemes:
    total = 0
    for _, tx in r.iterrows():
        cands = find_fee(s, tx)
        if not cands:
            continue
        # pick first? Usually should be unique. Take min fee among candidates
        best = min(cands, key=lambda f: f['fixed_amount'] + f['rate']*tx['eur_amount']/10000)
        total += best['fixed_amount'] + best['rate']*tx['eur_amount']/10000
    totals[s] = total
print(totals)
