import pandas as pd, json
df = pd.read_csv('data/payments.csv')
b = df[(df['merchant']=='Belles_cookbook_store') & (df['year']==2023)].copy()
b['date'] = pd.to_datetime(b['year'].astype(str)+'-'+b['day_of_year'].astype(str), format='%Y-%j')
b['month'] = b['date'].dt.month

with open('data/fees.json') as f:
    fees = json.load(f)

account_type = 'R'
capture_delay = '<3'

# Precompute monthly vol / fraud ratio
monthly_vol = b.groupby('month')['eur_amount'].sum().to_dict()
fraud = b[b['has_fraudulent_dispute']].groupby('month')['eur_amount'].sum().to_dict()
monthly_fraud_ratio = {m: fraud.get(m,0)/monthly_vol[m]*100 for m in monthly_vol}

def parse_range(rng, val):
    # e.g. '100k-1m'
    def toN(s):
        s=s.strip()
        if s.endswith('k'): return float(s[:-1])*1e3
        if s.endswith('m'): return float(s[:-1])*1e6
        if s.endswith('%'): return float(s[:-1])
        return float(s)
    if rng is None: return True
    s=rng.strip()
    if s.startswith('>'):
        return val > toN(s[1:])
    if s.startswith('<'):
        return val < toN(s[1:])
    if '-' in s:
        parts=s.split('-')
        return toN(parts[0]) <= val <= toN(parts[1])
    return False

def match_rule(rule, tx, mcc, monthly_vol_val, monthly_fraud_val, intracountry):
    if rule['card_scheme'] != tx['card_scheme']:
        return False
    if rule['account_type'] and account_type not in rule['account_type']:
        return False
    if rule['capture_delay'] is not None:
        if rule['capture_delay'] != capture_delay:
            # capture_delay in rule could be like '>5', check
            if not parse_range(rule['capture_delay'], 1):  # our value is 1 day
                return False
    if rule['monthly_fraud_level'] is not None:
        if not parse_range(rule['monthly_fraud_level'], monthly_fraud_val):
            return False
    if rule['monthly_volume'] is not None:
        if not parse_range(rule['monthly_volume'], monthly_vol_val):
            return False
    if rule['merchant_category_code'] and mcc not in rule['merchant_category_code']:
        return False
    if rule['is_credit'] is not None and rule['is_credit'] != tx['is_credit']:
        return False
    if rule['aci'] and tx['aci'] not in rule['aci']:
        return False
    if rule['intracountry'] is not None and rule['intracountry'] != intracountry:
        return False
    return True

def compute_total(mcc):
    total = 0.0
    for _, tx in b.iterrows():
        m = tx['month']
        mv = monthly_vol[m]
        mf = monthly_fraud_ratio[m]
        intracountry = (tx['issuing_country'] == tx['acquirer_country'])
        matched = None
        for rule in fees:
            if match_rule(rule, tx, mcc, mv, mf, intracountry):
                matched = rule
                break
        if matched is None:
            continue
        fee = matched['fixed_amount'] + matched['rate']*tx['eur_amount']/10000
        total += fee
    return total

orig = compute_total(5942)
new = compute_total(5911)
print('orig', orig)
print('new', new)
print('delta', new - orig)
