{"command": "python3 << 'EOF'
import pandas as pd, json
df = pd.read_csv('data/payments.csv')
df['date'] = pd.to_datetime(df['year'].astype(str)+df['day_of_year'].astype(str), format='%Y%j')
df['month'] = df['date'].dt.month
bj = df[(df['merchant']=='Belles_cookbook_store') & (df['month']==1)].copy()
vol = bj['eur_amount'].sum()
fraud_rate = bj[bj['has_fraudulent_dispute']]['eur_amount'].sum()/vol*100

fees = json.load(open('data/fees.json'))

def cd_match(rule_cd, cd=1):
    if rule_cd is None: return True
    return {'manual':False,'immediate':False,'<3':cd<3,'3-5':3<=cd<=5,'>5':cd>5}.get(rule_cd,False)
def vol_match(rv, v):
    if rv is None: return True
    return {'100k-1m':100000<=v<1000000,'<100k':v<100000,'1m-5m':1000000<=v<5000000,'>5m':v>=5000000}.get(rv,False)
def fraud_match(rf, fr):
    if rf is None: return True
    s = rf.replace('%','')
    if '-' in s: a,b=s.split('-'); return float(a)<=fr<=float(b)
    if s.startswith('<'): return fr<float(s[1:])
    if s.startswith('>'): return fr>float(s[1:])
    return False
def applies(rule, txn, vol, fr):
    if rule['card_scheme'] != txn['card_scheme']: return False
    if rule['account_type'] and 'R' not in rule['account_type']: return False
    if not cd_match(rule['capture_delay']): return False
    if not vol_match(rule['monthly_volume'], vol): return False
    if not fraud_match(rule['monthly_fraud_level'], fr): return False
    if rule['merchant_category_code'] and 5942 not in rule['merchant_category_code']: return False
    if rule['is_credit'] is not None and rule['is_credit'] != txn['is_credit']: return False
    if rule['aci'] and txn['aci'] not in rule['aci']: return False
    if rule['intracountry'] is not None:
        intr = 1.0 if txn['issuing_country']==txn['acquirer_country'] else 0.0
        if rule['intracountry'] != intr: return False
    return True

# Check unmatched patterns
missing_patterns = {}
for _, txn in bj.iterrows():
    matched = [r for r in fees if applies(r, txn, vol, fraud_rate)]
    if not matched:
        key = (txn['card_scheme'], txn['aci'], txn['is_credit'], txn['issuing_country']==txn['acquirer_country'])
        missing_patterns[key] = missing_patterns.get(key,0)+1
for k,v in sorted(missing_patterns.items()):
    print(k, v)
EOF"}

