        if x.endswith('m'): return float(x[:-1])*1_000_000
        return float(x)
    rv = rule_val.strip()
    if rv.startswith('>'):
        return num > parse(rv[1:])
    if rv.startswith('<'):
        return num < parse(rv[1:])
    if '-' in rv:
        a,b = rv.split('-')
        return parse(a) <= num <= parse(b)
    return False

