import json
with open('data/fees.json') as f:
    fees = json.load(f)
# Filter for NexPay, account_type H, MCC 5813
matches = []
for r in fees:
    if r['card_scheme'] != 'NexPay':
        continue
    at = r.get('account_type')
    if at not in (None, []) and 'H' not in at:
        continue
    mcc = r.get('merchant_category_code')
    if mcc not in (None, []) and 5813 not in mcc:
        continue
    matches.append(r)
print(len(matches))
for m in matches[:50]:
    print(m)
""}

