print("Jan volume:", jan_vol, "Fraud vol:", fraud_vol, "ratio:", fraud_vol/jan_vol*100)

def match_rule(rule, tx):
    if rule['card_scheme'] != tx['card_scheme']:
        return False
    if rule['account_type'] and account_type not in rule['account_type']:
        return False
    if rule['capture_delay'] is not None:
        cd = rule['capture_delay']
        if cd == 'immediate':
            if capture_delay != 'immediate': return False
        elif cd == '<3':
            if capture_delay not in ['immediate','1','2']: return False
        elif cd == '3-5':
            if capture_delay not in ['3','4','5']: return False
        elif cd == '>5':
            try:
                if int(capture_delay) <= 5: return False
            except: return False
        elif cd == 'manual':
            if capture_delay != 'manual': return False
    if rule['monthly_fraud_level'] is not None:
        # We'll assume fraud level applies - check merchant's Jan fraud ratio
        fr = fraud_vol/jan_vol*100
        lvl = rule['monthly_fraud_level']
        # parse
        if lvl.startswith('<'):
            if fr >= float(lvl[1:].replace('%','')): return False
        elif lvl.startswith('>'):
            if fr <= float(lvl[1:].replace('%','')): return False
        elif '-' in lvl:
            lo,hi = lvl.replace('%','').split('-')
            if not (float(lo) <= fr <= float(hi)): return False
    if rule['monthly_volume'] is not None:
        v = jan_vol
        mv = rule['monthly_volume']
        if mv == '100k-1m':
            if not (100000 <= v <= 1000000): return False
        elif mv.startswith('<'):
            thr = mv[1:]
            mult = 1000 if 'k' in thr else 1000000
            if v >= float(thr.replace('k','').replace('m',''))*mult: return False
        elif mv.startswith('>'):
            thr = mv[1:]
            mult = 1000 if 'k' in thr else 1000000
            if v <= float(thr.replace('k','').replace('m',''))*mult: return False
    if rule['merchant_category_code'] and mcc not in rule['merchant_category_code']:
        return False
    if rule['is_credit'] is not None:
        if rule['is_credit'] != tx['is_credit']: return False
    if rule['aci'] and tx['aci'] not in rule['aci']:
        return False
    if rule['intracountry'] is not None:
        intra = (tx['issuing_country'] == tx['acquirer_country'])
        if bool(rule['intracountry']) != intra: return False
    return True

def compute_fee(tx):
    matched = [r for r in fees if match_rule(r, tx)]
    if not matched:
        return None
    # take first? Should be one - use first
    r = matched[0]
    return r['fixed_amount'] + r['rate']*tx['eur_amount']/10000

# Baseline: current fees per scheme
m['fee'] = m.apply(compute_fee, axis=1)
print("Missing fees:", m['fee'].isna().sum())
print(m.groupby('card_scheme')['fee'].sum())
print("Total current fees:", m['fee'].sum())

# Now simulate: if all traffic goes to one scheme
totals = {}
for scheme in ['TransactPlus','GlobalCard','NexPay','SwiftCharge']:
    tmp = m.copy()
    tmp['card_scheme'] = scheme
    tmp['fee'] = tmp.apply(compute_fee, axis=1)
    totals[scheme] = tmp['fee'].sum()
    print(scheme, "total:", tmp['fee'].sum(), "missing:", tmp['fee'].isna().sum())
print(totals)
