import pandas as pd, json

df = pd.read_csv('data/payments.csv')
merchants = {m['merchant']: m for m in json.load(open('data/merchant_data.json'))}
fees = json.load(open('data/fees.json'))

merch = merchants['Crossfit_Hanna']
mcc = merch['merchant_category_code']
acct = merch['account_type']
cap_delay = merch['capture_delay']

# December 2023 monthly volume and fraud for Crossfit_Hanna
dec_mask = (df.merchant=='Crossfit_Hanna') & (df.year==2023) & (df.day_of_year>=335) & (df.day_of_year<=365)
dec = df[dec_mask]
monthly_volume = dec.eur_amount.sum()
fraud_vol = dec[dec.has_fraudulent_dispute==True].eur_amount.sum()
fraud_ratio = fraud_vol/monthly_volume if monthly_volume else 0
print('Monthly volume Dec:', monthly_volume, 'fraud ratio:', fraud_ratio)

def match_fee(row, fee):
    if fee['card_scheme'] != row['card_scheme']:
        return False
    if fee['account_type'] and acct not in fee['account_type']:
        return False
    if fee['capture_delay'] is not None:
        cd = fee['capture_delay']
        if cd == 'manual':
            if cap_delay != 'manual': return False
        elif cd == 'immediate':
            if cap_delay != 'immediate': return False
        elif cd == '<3':
            try: 
                if not (int(cap_delay) < 3): return False
            except: return False
        elif cd == '>5':
            try:
                if not (int(cap_delay) > 5): return False
            except: 
                if cap_delay != 'manual': return False  # manual could be >5? unsure
                return False
        elif cd == '3-5':
            try:
                v=int(cap_delay)
                if not (3<=v<=5): return False
            except: return False
    if fee['monthly_fraud_level'] is not None:
        mfl = fee['monthly_fraud_level']
        pct = fraud_ratio*100
        # parse
        if '%' in mfl:
            mfl2 = mfl.replace('%','')
            if '-' in mfl2:
                lo,hi = mfl2.split('-')
                if not (float(lo)<=pct<=float(hi)): return False
            elif mfl2.startswith('<'):
                if not (pct < float(mfl2[1:])): return False
            elif mfl2.startswith('>'):
                if not (pct > float(mfl2[1:])): return False
    if fee['monthly_volume'] is not None:
        mv = fee['monthly_volume']
        def parse(x):
            x=x.replace('k','e3').replace('m','e6')
            return float(x)
        if '-' in mv:
            lo,hi = mv.split('-')
            if not (parse(lo)<=monthly_volume<=parse(hi)): return False
        elif mv.startswith('<'):
            if not (monthly_volume<parse(mv[1:])): return False
        elif mv.startswith('>'):
            if not (monthly_volume>parse(mv[1:])): return False
    if fee['merchant_category_code'] and mcc not in fee['merchant_category_code']:
        return False
    if fee['is_credit'] is not None and fee['is_credit'] != row['is_credit']:
        return False
    if fee['aci'] and row['aci'] not in fee['aci']:
        return False
    if fee['intracountry'] is not None:
        intra = row['issuing_country']==row['acquirer_country']
        if fee['intracountry'] != intra:
            return False
    return True

sub = df[(df.merchant=='Crossfit_Hanna') & (df.year==2023) & (df.day_of_year==365)]
total = 0.0
unmatched = 0
for _,row in sub.iterrows():
    matched = [f for f in fees if match_fee(row,f)]
    if not matched:
        unmatched += 1
        continue
    # take first matching? Usually should be unique
    if len(matched)>1:
        pass  # multiple
    f = matched[0]
    fee_val = f['fixed_amount'] + f['rate']*row['eur_amount']/10000
    total += fee_val
print('Total fees:', round(total,2), 'unmatched:', unmatched)
