merchant_mcc = 5942
merchant_account = 'R'
# capture_delay '1' means 1 day = falls under '<3'
merchant_capture = '<3'
monthly_volume_val = 99029.66  # falls in '5k-100k'? Actually 99k is in 5k-100k range
# but let's check the ranges
fraud_level_val = 0.0816  # ~8.16%

def match_range(rule_val, actual):
    if rule_val is None:
        return True
    # ranges like "100k-1m", "5k-100k", "<5k", ">1m"
    s = rule_val
    def parse(x):
        x = x.strip()
        if x.endswith('k'): return float(x[:-1])*1000
        if x.endswith('m'): return float(x[:-1])*1_000_000
        if x.endswith('%'): return float(x[:-1])/100
        return float(x)
    if '-' in s and not s.startswith('<') and not s.startswith('>'):
        lo, hi = s.split('-')
        return parse(lo) <= actual <= parse(hi)
    if s.startswith('<'):
        return actual < parse(s[1:])
    if s.startswith('>'):
        return actual > parse(s[1:])
    return False

def match_fraud(rule, actual):
    if rule is None: return True
    s = rule
    def parse(x):
        x=x.strip()
        if x.endswith('%'): return float(x[:-1])/100
        return float(x)
    if '-' in s:
        lo,hi=s.split('-')
        return parse(lo) <= actual <= parse(hi)
    if s.startswith('<'): return actual < parse(s[1:])
    if s.startswith('>'): return actual > parse(s[1:])
    return False

def find_fee(row):
    intracountry = row['acquirer_country'] == row['issuing_country']
    for r in fees:
        if r['card_scheme'] != row['card_scheme']: continue
        if r['account_type'] and merchant_account not in r['account_type']: continue
        if r['capture_delay'] is not None and r['capture_delay'] != merchant_capture:
            # need to handle: capture_delay rule could be '<3' matches, or 'manual' etc.
            # our merchant capture is '<3' effectively. Skip if not matching.
            # But actually rule capture_delay is a string like '3-5','>5','<3','immediate','manual'
            if r['capture_delay'] != merchant_capture:
                continue
        if r['monthly_fraud_level'] is not None and not match_fraud(r['monthly_fraud_level'], fraud_level_val):
            continue
        if r['monthly_volume'] is not None and not match_range(r['monthly_volume'], monthly_volume_val):
            continue
        if r['merchant_category_code'] and merchant_mcc not in r['merchant_category_code']: continue
        if r['is_credit'] is not None and r['is_credit'] != row['is_credit']: continue
        if r['aci'] and row['aci'] not in r['aci']: continue
        if r['intracountry'] is not None and r['intracountry'] != intracountry: continue
        return r['fixed_amount'] + r['rate'] * row['eur_amount'] / 10000
    return None

b_sept = df[(df['merchant']=='Belles_cookbook_store') & (df['year']==2023) & (df['day_of_year']>=244) & (df['day_of_year']<=273)].copy()
b_sept['fee'] = b_sept.apply(find_fee, axis=1)
print("Null fees:", b_sept['fee'].isna().sum())
print("Total fees:", b_sept['fee'].sum())
print(round(b_sept['fee'].sum(),2))
