payments = pd.read_csv('data/payments.csv')
with open('data/fees.json') as f:
    fees = json.load(f)
with open('data/merchant_data.json') as f:
    merchants = json.load(f)

merchant = [m for m in merchants if m['merchant']=='Golfclub_Baron_Friso'][0]
mcc = merchant['merchant_category_code']
acct = merchant['account_type']
capture_delay = merchant['capture_delay']

june_start = dt.date(2023,6,1).timetuple().tm_yday
june_end = dt.date(2023,6,30).timetuple().tm_yday

p = payments[(payments['merchant']=='Golfclub_Baron_Friso') & (payments['year']==2023) & (payments['day_of_year']>=june_start) & (payments['day_of_year']<=june_end)].copy()

# Monthly volume and fraud for June for this merchant
month_vol = p['eur_amount'].sum()
fraud_vol = p.loc[p['has_fraudulent_dispute']==True, 'eur_amount'].sum()
fraud_ratio = fraud_vol / month_vol * 100
print("June volume:", month_vol, "fraud%:", fraud_ratio)

def vol_match(rule_vol, vol):
    if rule_vol is None: return True
    # formats: '100k-1m', '<100k', '>5m' etc
    s = rule_vol.replace('k','e3').replace('m','e6')
    if '-' in s:
        a,b = s.split('-')
        return float(a) <= vol <= float(b)
    if s.startswith('<'): return vol < float(s[1:])
    if s.startswith('>'): return vol > float(s[1:])
    return False

def fraud_match(rule_f, f):
    if rule_f is None: return True
    s = rule_f.replace('%','')
    if '-' in s:
        a,b = s.split('-')
        return float(a) <= f <= float(b)
    if s.startswith('<'): return f < float(s[1:])
    if s.startswith('>'): return f > float(s[1:])
    return False

def find_fee(row):
    matches = []
    for r in fees:
        if r['card_scheme'] != row['card_scheme']: continue
        if r['account_type'] and acct not in r['account_type']: continue
        if r['capture_delay'] is not None:
            cd = r['capture_delay']
            try:
