                cap = None
            if cd == 'manual':
                if capture_delay != 'manual': continue
            elif cd == 'immediate':
                if capture_delay != 'immediate': continue
            elif cd == '<3':
                if cap is None or not (cap<3): continue
            elif cd == '>5':
                if cap is None or not (cap>5): continue
            elif cd == '3-5':
                if cap is None or not (3<=cap<=5): continue
        if r['monthly_fraud_level'] is not None and not fraud_match(r['monthly_fraud_level'], fraud_ratio): continue
        if r['monthly_volume'] is not None and not vol_match(r['monthly_volume'], month_vol): continue
        if r['merchant_category_code'] and mcc not in r['merchant_category_code']: continue
        if r['is_credit'] is not None and r['is_credit'] != bool(row['is_credit']): continue
        if r['aci'] and row['aci'] not in r['aci']: continue
        if r['intracountry'] is not None:
            intra = (row['issuing_country'] == row['acquirer_country'])
            if bool(r['intracountry']) != intra: continue
        matches.append(r)
    if len(matches) != 1:
        return matches
    r = matches[0]
    return r['fixed_amount'] + r['rate'] * row['eur_amount'] / 10000

