{"command": "python3 <<'EOF'
import pandas as pd, json
df = pd.read_csv('data/payments.csv')
fees = json.load(open('data/fees.json'))
merchants = json.load(open('data/merchant_data.json'))

merchant = 'Golfclub_Baron_Friso'
m = next(x for x in merchants if x['merchant']==merchant)
mcc = m['merchant_category_code']
acct = m['account_type']
capture_delay = m['capture_delay']

sub = df[(df['merchant']==merchant) & (df['day_of_year']==12) & (df['year']==2023)]

def match_cd(rule_cd, mcd):
    if rule_cd is None: return True
    try: mcd_i = int(mcd)
    except: return rule_cd == mcd
    if rule_cd == 'immediate': return False
    if rule_cd == 'manual': return False
    if rule_cd == '<3': return mcd_i < 3
    if rule_cd == '3-5': return 3 <= mcd_i <= 5
    if rule_cd == '>5': return mcd_i > 5
    return False

def match_fraud(rng, v):
    if rng is None: return True
    if v is None: return False
    def parse(s): return float(s.replace('%',''))/100
    if rng.startswith('<'): return v < parse(rng[1:])
    if rng.startswith('>'): return v > parse(rng[1:])
    if '-' in rng: a,b=rng.split('-'); return parse(a)<=v<=parse(b)

def match_vol(rng, v):
    if rng is None: return True
    def parse(s): return float(s.lower().replace('k','e3').replace('m','e6'))
    if rng.startswith('<'): return v < parse(rng[1:])
    if rng.startswith('>'): return v > parse(rng[1:])
    if '-' in rng: a,b=rng.split('-'); return parse(a)<=v<=parse(b)

def compute(monthly_volume, fraud_level, agg='mean'):
    total = 0.0
    stats = {'matched':0,'multi':0,'unmatched':0}
    for _, tx in sub.iterrows():
        matches=[]
        for r in fees:
            if r['card_scheme']!=tx['card_scheme']: continue
            if r['account_type'] and acct not in r['account_type']: continue
            if not match_cd(r['capture_delay'], capture_delay): continue
            if not match_fraud(r['monthly_fraud_level'], fraud_level): continue
            if not match_vol(r['monthly_volume'], monthly_volume): continue
            if r['merchant_category_code'] and mcc not in r['merchant_category_code']: continue
            if r['is_credit'] is not None and r['is_credit']!=bool(tx['is_credit']): continue
            if r['aci'] and tx['aci'] not in r['aci']: continue
            if r['intracountry'] is not None:
                intra = (tx['issuing_country']==tx['acquirer_country'])
                if bool(r['intracountry'])!=intra: continue
            matches.append(r)
        if not matches:
            stats['unmatched']+=1
        elif len(matches)==1:
            stats['matched']+=1
            r=matches[0]; total += r['fixed_amount']+r['rate']*tx['eur_amount']/10000
        else:
            stats['multi']+=1
            fees_list = [r['fixed_amount']+r['rate']*tx['eur_amount']/10000 for r in matches]
            if agg=='mean': total += sum(fees_list)/len(fees_list)
            elif agg=='min': total += min(fees_list)
            elif agg=='max': total += max(fees_list)
    return total, stats

# With Jan monthly volume, fraud None
jan = df[(df['merchant']==merchant) & (df['year']==2023) & (df['day_of_year']<=31)]
mv = jan['eur_amount'].sum()
fraud = jan[jan['has_fraudulent_dispute']]['eur_amount'].sum()/mv
print("Jan volume:", mv, "Jan fraud:", fraud)
for scenario in [(mv, fraud), (mv, None), (0, None)]:
    for agg in ['mean','min','max']:
        t,s = compute(scenario[0], scenario[1], agg)
        print(scenario, agg, t, s)
